package conditionals;

public class Strring {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		// When we work with strings, the methodology to compare them is different, as we can see here.
		
		String string1 = "Hello";
		
		if (string1.equals("Hello")) {
			System.out.println("Hello = Hello (woooooooow)");
		} else {
			System.out.println("Something really weird had to happen, try again.");
		}
		
	}

}
